def find_vulnerabilities_fixed(vulnerabilities: Dict[str, Any], fixes: List[Fix]) -> List[Vulnerability]:
    fixed = []
    applied_fixes = [fix for fix in fixes if fix.status == 'APPLIED']

    for fix in applied_fixes:
        for vuln in vulnerabilities:
            if vuln.package_name == fix.package and str(vuln.analyzed_requirement.specifier) == fix.previous_spec:
                fixed.append(vuln)

    return fixed

def find_vulnerabilities_fixed(vulnerabilities: Dict[str, Any], fixes: List
    [Fix]) ->List[Vulnerability]:
    fixed = []

    if not fixes or not vulnerabilities:
        return fixed

    applied_fixes = [fix for fix in fixes if getattr(fix, 'status', None) == 'APPLIED']

    for fix in applied_fixes:
        for vuln in vulnerabilities:
            if (vuln.package_name == fix.package and 
                    str(vuln.analyzed_requirement.specifier) == fix.previous_spec):
                if vuln not in fixed:
                    fixed.append(vuln)

    return fixed
